Backfill logic

{noformat}const {DB} = require('../db')
const {buildConfig} = require('../config')
const uuid = require('uuid')


const generating_fake_courier_metrica = async (courierStatistics, courierData) => {
    const courierStatisticsDb = new DB(courierStatistics);
    const courierDataDb = new DB(courierData);


    try {
        const fleetId = 8;
        const howManyDaysBack = 182;
        let couriers = (await courierDataDb.query(
            "select * from courier where delivery_fleet_id = " + fleetId  + ";"
        )).results;
        couriers = couriers.sort((a,b) => a.id - b.id);

        // Generate dates
        const datesForSQL = [];
        const today = new Date();
        for (let i = 1; i <= howManyDaysBack; i++) {
            const date = new Date(today.getTime());
            date.setDate(today.getDate() - i);
            datesForSQL.push(date.toISOString().split('T')[0]);
        }

        // --- Bulk Insert Logic ---
        const batchSize = 50; // Insert 50 rows at a time
        let valueRows = []; // Array to hold the values for one batch
        let totalInserted = 0;
        let courierCnt = 0;

        for (const courier of couriers) {          
            for (const date of datesForSQL) {
                // Prepare values for one row
                const rowValues = [
                    courier.delivery_fleet_id,
                    `'${date}'`, // Date needs quotes
                    courier.city_id,
                    courier.id,
                    `'${courier.uid}'`,
                    getRandomInt(3), // orders_proposed
                    getRandomInt(16), // orders_accepted
                    getRandomInt(23), // orders_delivered
                    getRandomInt(78), // online_time_with_order_minutes
                    getRandomInt(12), // online_time_without_order_minutes
                    getRandomInt(888), // total_earnings_net_value (assuming numeric)
                    getRandomInt(888), // total_earnings_gross_value (assuming numeric)
                    getRandomInt(888), // balance (assuming numeric)
                    "'2025-10-28 10:00:00'",
                    "'eur'" // currency needs quotes
                ];
                valueRows.push(`(${rowValues.join(", ")})`); // Add formatted row to batch

                // If batch is full, execute the INSERT
                if (valueRows.length >= batchSize) {
                    const insertQuery = `
                        INSERT INTO courier_statistics (
                            fleet_id, date, city_id, courier_id, courier_uid, orders_proposed, orders_accepted, orders_delivered, online_time_with_order_minutes, online_time_without_order_minutes, total_earnings_net_value, total_earnings_gross_value, balance, last_time_online, currency
                        ) VALUES ${valueRows.join(", ")}
                    `;
                    await courierStatisticsDb.query(insertQuery);
                    totalInserted += valueRows.length;
                    valueRows = []; // Reset the batch
                    console.log("Inserted batch. Total so far: " + totalInserted);
                }
            }
            courierCnt++;

        }

        // Insert any remaining rows after the loop
        if (valueRows.length > 0) {
            const insertQuery = `
                INSERT INTO courier_statistics (
                         fleet_id, date, city_id, courier_id, courier_uid, orders_proposed, orders_accepted, orders_delivered, online_time_with_order_minutes, online_time_without_order_minutes, total_earnings_net_value, total_earnings_gross_value, balance, last_time_online, currency
                ) VALUES ${valueRows.join(", ")}
            `;
            await courierStatisticsDb.query(insertQuery);
            totalInserted += valueRows.length;
            console.log("Inserted final batch. Total inserted: " + totalInserted);
            valueRows = [];
        }
        // --- End Bulk Insert Logic ---

        const results = (await courierStatisticsDb.query(
            "select count(*) from courier_statistics"
        )).results;

        console.log("result length: " + results.length); // Log length for confirmation

        await courierStatisticsDb.commit();

    } catch (err) {
        console.error("Error occurred:", err);
        // Rollback if error
        if (courierStatisticsDb) await courierStatisticsDb.rollback();
    } finally {
        // Close connections
        if (courierStatisticsDb) await courierStatisticsDb.end();
        if (courierDataDb) await courierDataDb.end();
    }
}
function getRandomInt(max) {
    return Math.floor(Math.random() * max);
}

generating_fake_courier_metrica(
    buildConfig('taxify_delivery_courier_statistics_deliveryglobal', 'konstantin.konashenkov@341745'),
    buildConfig('taxify_delivery_courier', 'konstantin.konashenkov@281746'),
){noformat}

