{noformat}import osmium
import csv
import os

# Build segment map from OSM
class HighwaySegmentPrinter(osmium.SimpleHandler):
    def __init__(self):
        super().__init__()
        self.segment_map = {}

    def way(self, w):
        if 'highway' in w.tags:
            highway_type = w.tags['highway']
            for i in range(len(w.nodes) - 1):
                n1 = w.nodes[i]
                n2 = w.nodes[i + 1]
                key = (n1.ref, n2.ref)
                self.segment_map[key] = highway_type

# Parse OSM file
osm_file = 'city.osm.pbf'
handler = HighwaySegmentPrinter()
handler.apply_file(osm_file)

# Folder with CSV files
csv_folder = '2025-09-25-data'
for filename in os.listdir(csv_folder):
    if filename.endswith('.csv'):
        input_path = os.path.join(csv_folder, filename)
        output_path = os.path.join(csv_folder, filename.replace('.csv', '_modified.csv'))
        with open(input_path) as infile, open(output_path, 'w', newline='') as outfile:
            reader = csv.reader(infile)
            writer = csv.writer(outfile)
            for row in reader:
                node1, node2, speed = int(row[0]), int(row[1]), float(row[2])
                hwy_type = handler.segment_map.get((node1, node2), None)
                # Deprioritize residential roads
                if hwy_type == 'residential':
                    rate = 0.9 * speed
                else:
                    rate = speed
                writer.writerow([node1, node2, speed, rate]){noformat}

